export interface ConnectorConfig {
  /** Slack bot token with chat:write scope. Env var: SLACK_BOT_TOKEN */
  slackBotToken: string
  /** Slack channel ID to post the message to. Env var: SLACK_CHANNEL_ID */
  slackChannelId: string
  /** Optional fetch implementation for testing or custom HTTP clients. */
  fetch?: typeof fetch
}

export interface CalendlyInviteeCreatedPayload {
  event: 'invitee.created'
  payload: {
    invitee: {
      name: string
      email: string
    }
    answers: Record<string, string>
    uri: string
  }
}

export interface SlackPostMessageResponse {
  ok: boolean
  channel: string
  ts: string
}

export interface HandleResult {
  slackMessageTs: string
  slackChannel: string
}

function formatAnswers(answers: Record<string, string>): string {
  if (!answers || Object.keys(answers).length === 0) {
    return 'No answers provided.'
  }
  return Object.entries(answers)
    .map(([question, answer]) => `${question}: ${answer}`)
    .join('\n')
}

export async function handle(
  payload: CalendlyInviteeCreatedPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required fields
  if (!payload.payload?.invitee?.name) {
    throw new Error('Missing required field: payload.invitee.name')
  }
  if (!payload.payload?.invitee?.email) {
    throw new Error('Missing required field: payload.invitee.email')
  }
  if (!payload.payload?.answers) {
    throw new Error('Missing required field: payload.answers')
  }

  const { name, email } = payload.payload.invitee
  const answers = payload.payload.answers

  const formattedAnswers = formatAnswers(answers)
  const text = `Invitee: ${name}\nEmail: ${email}\nAnswers:\n${formattedAnswers}`

  const response = await fetchImpl('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      channel: config.slackChannelId,
      text,
    }),
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} for POST https://slack.com/api/chat.postMessage`)
  }

  const data = await response.json() as SlackPostMessageResponse

  if (!data.ok) {
    throw new Error(`Slack API returned ok=false: ${JSON.stringify(data)}`)
  }

  return {
    slackMessageTs: data.ts,
    slackChannel: data.channel,
  }
}

